#ifndef ZOVUTILS_INSTALL_BACKEND_H
#define ZOVUTILS_INSTALL_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <utime.h>
static inline int zov_install_mkdirs(const char*p,mode_t mode){char*b=(char*)malloc(strlen(p)+1);if(!b)return 0;strcpy(b,p);for(char*q=b+1;*q;q++)if(*q=='/'){*q=0;if(mkdir(b,mode)<0&&errno!=EEXIST){free(b);return 0;}*q='/';}if(mkdir(b,mode)<0&&errno!=EEXIST){free(b);return 0;}free(b);return 1;}
static inline char*zov_install_join(const char*a,const char*b){size_t x=strlen(a),y=strlen(b);char*p=(char*)malloc(x+y+2);if(!p)return NULL;memcpy(p,a,x);size_t n=x;if(n&&p[n-1]!='/')p[n++]='/';memcpy(p+n,b,y+1);return p;}
static inline char*zov_install_dup(const char*s){size_t n=strlen(s);char*p=(char*)malloc(n+1);if(p)memcpy(p,s,n+1);return p;}
static inline const char*zov_install_base(const char*p){const char*q=strrchr(p,'/');return q?q+1:p;}
static inline int zov_install_run(int argc,char**argv){mode_t mode=0755;int have_mode=0,dirs=0,make_parents=0,preserve=0,verbose=0,toflag=0,nf=0;const char*targetdir=NULL;char**ops=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!ops)return 1;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: install [OPTION]... [-T] SOURCE DEST\n  or:  install [OPTION]... SOURCE... DIRECTORY\n  or:  install [OPTION]... -t DIRECTORY SOURCE...\n  or:  install [OPTION]... -d DIRECTORY...\nCopy files and set attributes.\n  -d, --directory        create directories\n  -D                      create all leading components of DEST\n  -m, --mode=MODE        set permission mode\n  -p, --preserve-timestamps\n      --help              display this help and exit\n      --version           output version information and exit");free(ops);return 0;}if(!strcmp(a,"--version")){puts("install (zovutils) 0.10.18");free(ops);return 0;}if(!strcmp(a,"-d")||!strcmp(a,"--directory")){dirs=1;continue;}if(!strcmp(a,"-D")){make_parents=1;continue;}if(!strcmp(a,"-p")||!strcmp(a,"--preserve-timestamps")){preserve=1;continue;}if(!strcmp(a,"-v")||!strcmp(a,"--verbose")){verbose=1;continue;}if(!strcmp(a,"-t")||!strcmp(a,"--target-directory")){if(i+1>=argc){free(ops);return 1;}targetdir=argv[++i];continue;}if(!strcmp(a,"-m")||!strcmp(a,"--mode")){if(i+1>=argc){free(ops);return 1;}char*e;unsigned long x=strtoul(argv[++i],&e,8);if(*e||x>07777){fprintf(stderr,"install: invalid mode '%s'\n",argv[i]);free(ops);return 1;}mode=(mode_t)x;have_mode=1;continue;}if(!strncmp(a,"--mode=",7)){char*e;unsigned long x=strtoul(a+7,&e,8);if(*e||x>07777){fprintf(stderr,"install: invalid mode '%s'\n",a+7);free(ops);return 1;}mode=(mode_t)x;have_mode=1;continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"install: unrecognized option '%s'\nTry 'install --help' for more information.\n",a);free(ops);return 1;}ops[nf++]=(char*)a;}int status=0;if(dirs){if(!nf){fprintf(stderr,"install: missing operand\nTry 'install --help' for more information.\n");free(ops);return 1;}for(int i=0;i<nf;i++)if(!zov_install_mkdirs(ops[i],mode)){fprintf(stderr,"install: cannot create directory '%s': %s\n",ops[i],strerror(errno));status=1;}free(ops);return status;}if(targetdir){struct stat st;if(stat(targetdir,&st)<0||!S_ISDIR(st.st_mode)){fprintf(stderr,"install: target directory '%s' does not exist\n",targetdir);free(ops);return 1;}}if(nf<2&&!targetdir){fprintf(stderr,"install: missing destination file operand\nTry 'install --help' for more information.\n");free(ops);return 1;}const char*dest=targetdir?targetdir:ops[nf-1];int sources=targetdir?nf:nf-1;struct stat ds;int dest_is_dir=targetdir||(stat(dest,&ds)==0&&S_ISDIR(ds.st_mode));if(sources>1&&!dest_is_dir){fprintf(stderr,"install: target '%s' is not a directory\n",dest);free(ops);return 1;}for(int i=0;i<sources;i++){const char*src=ops[i];char*outname=dest_is_dir?zov_install_join(dest,zov_install_base(src)):zov_install_dup(dest);if(!outname){status=1;continue;}struct stat st;if(stat(src,&st)<0){fprintf(stderr,"install: cannot stat '%s': %s\n",src,strerror(errno));free(outname);status=1;continue;}if(make_parents){char*slash=strrchr(outname,'/');if(slash){*slash=0;if(!zov_install_mkdirs(*outname?outname:"/",0755)){fprintf(stderr,"install: cannot create directory '%s': %s\n",outname,strerror(errno));status=1;}*slash='/';}}FILE*in=fopen(src,"rb"),*out=fopen(outname,"wb");if(!in||!out){fprintf(stderr,"install: cannot create regular file '%s': %s\n",outname,strerror(errno));if(in)fclose(in);if(out)fclose(out);free(outname);status=1;continue;}unsigned char buf[16384];size_t n;while((n=fread(buf,1,sizeof(buf),in)))if(fwrite(buf,1,n,out)!=n){status=1;break;}if(ferror(in))status=1;fclose(in);fclose(out);if(chmod(outname,have_mode?mode:mode)<0)status=1;if(preserve){struct utimbuf u;u.actime=st.st_atime;u.modtime=st.st_mtime;utime(outname,&u);}if(verbose)printf("'%s' -> '%s'\n",src,outname);free(outname);}free(ops);return status;}
#endif
